function archiveEntries() {
    $zip = new ZipArchive();
    if ($zip->open('/srv/archives/' . $_GET['archive']) !== true) {
        return [];
    }
    $names = [];
    for ($i = 0; $i < $zip->numFiles; $i++) {
        $names[] = $zip->getNameIndex($i);
    }
    return $names;
}

