function downloadDoc() {
    $base = realpath('/srv/docs');
    $name = basename($_GET['doc'] ?? '');
    $path = realpath($base . DIRECTORY_SEPARATOR . $name);
    if ($name === '' || $path === false || !str_starts_with($path, $base . DIRECTORY_SEPARATOR) || !is_file($path)) {
        http_response_code(404);
        return;
    }
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="' . rawurlencode($name) . '"');
    readfile($path);
}

function mailgunClient(): Mailgun\Mailgun {
    $key = getenv('MAILGUN_API_KEY');
    if ($key === false || $key === '') {
        throw new RuntimeException('MAILGUN_API_KEY is not set');
    }
    return Mailgun\Mailgun::create($key);
}

function latestArticles(PDO $pdo): array {
    $limit = min(100, max(1, (int) ($_GET['limit'] ?? 20)));
    $stmt = $pdo->query("SELECT id, title FROM articles ORDER BY published_at DESC LIMIT $limit");
    return $stmt->fetchAll(PDO::FETCH_ASSOC);
}

function ticketById($pg) {
    $id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
    if ($id === false || $id === null) {
        http_response_code(400);
        exit;
    }
    $res = pg_query_params($pg, 'SELECT subject, status FROM tickets WHERE id = $1', [$id]);
    return pg_fetch_assoc($res);
}

function cachedMenu(): array {
    $file = __DIR__ . '/../var/cache/menu.cache';
    if (!is_file($file)) {
        return [];
    }
    $menu = unserialize(file_get_contents($file), ['allowed_classes' => false]);
    return is_array($menu) ? $menu : [];
}

$app->post('/cart', function ($request, $response) {
    $data = json_decode((string) $request->getBody(), true, 16, JSON_THROW_ON_ERROR);
    $qty = max(0, (int) ($data['qty'] ?? 0));
    $response->getBody()->write(json_encode(['qty' => $qty], JSON_THROW_ON_ERROR));
    return $response->withHeader('Content-Type', 'application/json');
});

function listCustomers(mysqli $db): array {
    $columns = ['name', 'created_at', 'country'];
    $sort = in_array($_GET['sort'] ?? '', $columns, true) ? $_GET['sort'] : 'name';
    $dir = ($_GET['dir'] ?? '') === 'desc' ? 'DESC' : 'ASC';
    return $db->query("SELECT id, name, country FROM customers ORDER BY $sort $dir")->fetch_all(MYSQLI_ASSOC);
}
